<?php

namespace Drupal\email_attachment_demo\Hook;

use Drupal\Core\Hook\Attribute\Hook;

/**
 * Hook implementations for email_attachment_demo.
 */
class EmailAttachmentDemoHooks {

  /**
   * Implements hook_mail_alter().
   *
   * This is an example implementation to show how to alter emails generated by
   * other modules. Go to the URL /contact to send an email. It will arrive with
   * this file attached.
   */
  #[Hook('mail_alter')]
  public function mailAlter(&$message): void {
    if ($message['id'] != 'contact_page_mail') {
      return;
    }
    $message['params'] += [
      'attachment' => [
        'filename' => __FILE__,
      ],
    ];
  }

}
